# Compare contamination: left/right-strip mirror tiling vs top/bottom-strip mirror tiling, via 4x4 contact sheets
def bg_lr(arr, w=56):
    L = arr[:, :w]; R = arr[:, -w:]
    return np.concatenate([L, L[:, ::-1], R[:, ::-1], R], axis=1)
def bg_tb(arr, w=56):
    T = arr[:w]; B = arr[-w:]
    return np.concatenate([T, T[::-1], B[::-1], B], axis=0)
def save_model_png(a, fn):
    pad = np.pad(a, ((16,16),(16,16),(0,0)), mode='reflect')
    Image.fromarray(pad).save(fn)
def sheet(arrs, fn, n=4):
    t = 224//n
    canvas = np.zeros((224,224,3), np.uint8)
    for k, a in enumerate(arrs[:n*n]):
        th = np.asarray(Image.fromarray(a).resize((t,t), Image.BILINEAR))
        r, c = divmod(k, n)
        canvas[r*t:(r+1)*t, c*t:(c+1)*t] = th
    save_model_png(canvas, fn)
